import React, { useState, useEffect } from 'react';
import { useMutation } from 'react-query';
import { X, ArrowRight, Check, Settings, Info } from 'lucide-react';
import toast from 'react-hot-toast';

import LoadingSpinner from './LoadingSpinner';

const VariantMappingModal = ({ 
  mainProduct, 
  targetProduct, 
  isOpen, 
  onClose, 
  onSave 
}) => {
  const [variantMapping, setVariantMapping] = useState({
    syncOptions: [],
    enabled: true
  });
  const [suggestions, setSuggestions] = useState([]);
  const [isLoading, setIsLoading] = useState(false);

  // Generate variant mapping suggestions
  const generateMappingMutation = useMutation(
    async ({ mainProductId, targetProductId }) => {
      const response = await fetch('/api/bundles/variant-mapping', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ mainProductId, targetProductId })
      });

      if (!response.ok) {
        throw new Error('Failed to generate variant mapping');
      }

      return response.json();
    },
    {
      onSuccess: (data) => {
        if (data.success) {
          setSuggestions(data.data.variantMapping.suggestions || []);
          setVariantMapping(prev => ({
            ...prev,
            syncOptions: data.data.variantMapping.syncOptions || []
          }));
        }
      },
      onError: (error) => {
        toast.error(error.message || 'Failed to generate mapping suggestions');
      }
    }
  );

  useEffect(() => {
    if (isOpen && mainProduct && targetProduct) {
      setIsLoading(true);
      generateMappingMutation.mutate({
        mainProductId: mainProduct.id,
        targetProductId: targetProduct.id
      });
      setIsLoading(false);
    }
  }, [isOpen, mainProduct?.id, targetProduct?.id]);

  const addSyncOption = () => {
    setVariantMapping(prev => ({
      ...prev,
      syncOptions: [
        ...prev.syncOptions,
        {
          mainOption: '',
          targetOption: '',
          confidence: 0
        }
      ]
    }));
  };

  const updateSyncOption = (index, field, value) => {
    setVariantMapping(prev => ({
      ...prev,
      syncOptions: prev.syncOptions.map((option, i) =>
        i === index ? { ...option, [field]: value } : option
      )
    }));
  };

  const removeSyncOption = (index) => {
    setVariantMapping(prev => ({
      ...prev,
      syncOptions: prev.syncOptions.filter((_, i) => i !== index)
    }));
  };

  const handleSave = () => {
    if (variantMapping.syncOptions.length === 0 && variantMapping.enabled) {
      toast.error('Please add at least one variant sync option or disable variant sync');
      return;
    }

    onSave(variantMapping);
    onClose();
  };

  const getOptionValues = (product, optionName) => {
    const option = product.options?.find(opt => opt.name === optionName);
    return option?.values || [];
  };

  const previewVariantMatches = () => {
    if (!mainProduct?.variants || !targetProduct?.variants || !variantMapping.syncOptions.length) {
      return [];
    }

    const matches = [];

    mainProduct.variants.forEach(mainVariant => {
      const matchingTarget = targetProduct.variants.find(targetVariant => {
        return variantMapping.syncOptions.every(syncOption => {
          const mainValue = getVariantOptionValue(mainVariant, syncOption.mainOption, mainProduct);
          const targetValue = getVariantOptionValue(targetVariant, syncOption.targetOption, targetProduct);
          return mainValue === targetValue;
        });
      });

      if (matchingTarget) {
        matches.push({
          main: mainVariant,
          target: matchingTarget,
          match: true
        });
      } else {
        matches.push({
          main: mainVariant,
          target: null,
          match: false
        });
      }
    });

    return matches;
  };

  const getVariantOptionValue = (variant, optionName, product) => {
    const optionIndex = product.options?.findIndex(opt => opt.name === optionName);
    if (optionIndex === -1) return null;

    switch (optionIndex) {
      case 0: return variant.option1;
      case 1: return variant.option2;
      case 2: return variant.option3;
      default: return null;
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto">
      <div className="flex items-center justify-center min-h-screen px-4 pt-4 pb-20 text-center sm:p-0">
        <div className="fixed inset-0 transition-opacity bg-gray-500 bg-opacity-75" onClick={onClose} />

        <div className="relative inline-block w-full max-w-5xl p-6 overflow-hidden text-left align-bottom transition-all transform bg-white shadow-xl rounded-lg sm:my-8 sm:align-middle">
          {/* Header */}
          <div className="flex items-center justify-between mb-6">
            <div>
              <h3 className="text-lg font-medium text-gray-900 flex items-center">
                <Settings className="w-5 h-5 mr-2" />
                Variant Synchronization
              </h3>
              <p className="text-sm text-gray-500">
                Configure how variants sync between "{mainProduct?.title}" and "{targetProduct?.title}"
              </p>
            </div>
            <button
              onClick={onClose}
              className="p-2 text-gray-400 hover:text-gray-600 rounded-lg hover:bg-gray-100"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          <div className="space-y-6">
            {/* Enable/Disable Toggle */}
            <div className="flex items-center justify-between p-4 bg-blue-50 rounded-lg">
              <div>
                <h4 className="font-medium text-blue-900">Variant Synchronization</h4>
                <p className="text-sm text-blue-700">
                  When enabled, variant selections will sync across bundle products
                </p>
              </div>
              <label className="flex items-center">
                <input
                  type="checkbox"
                  checked={variantMapping.enabled}
                  onChange={(e) => setVariantMapping(prev => ({ ...prev, enabled: e.target.checked }))}
                  className="rounded border-blue-300 text-blue-600 focus:ring-blue-500"
                />
                <span className="ml-2 text-sm font-medium text-blue-900">Enable</span>
              </label>
            </div>

            {variantMapping.enabled && (
              <>
                {/* Sync Options Configuration */}
                <div>
                  <div className="flex items-center justify-between mb-4">
                    <h4 className="font-medium text-gray-900">Sync Options</h4>
                    <button
                      onClick={addSyncOption}
                      className="btn-secondary text-sm"
                    >
                      Add Sync Rule
                    </button>
                  </div>

                  {isLoading && (
                    <div className="flex items-center justify-center py-8">
                      <LoadingSpinner size="md" className="mr-2" />
                      <span>Analyzing variants...</span>
                    </div>
                  )}

                  <div className="space-y-3">
                    {variantMapping.syncOptions.map((syncOption, index) => (
                      <div key={index} className="flex items-center space-x-4 p-4 border rounded-lg bg-gray-50">
                        <div className="flex-1">
                          <label className="label text-xs">Main Product Option</label>
                          <select
                            value={syncOption.mainOption}
                            onChange={(e) => updateSyncOption(index, 'mainOption', e.target.value)}
                            className="input text-sm"
                          >
                            <option value="">Select option...</option>
                            {mainProduct?.options?.map(option => (
                              <option key={option.name} value={option.name}>
                                {option.name} ({option.values?.length || 0} values)
                              </option>
                            ))}
                          </select>
                        </div>

                        <ArrowRight className="w-4 h-4 text-gray-400" />

                        <div className="flex-1">
                          <label className="label text-xs">Target Product Option</label>
                          <select
                            value={syncOption.targetOption}
                            onChange={(e) => updateSyncOption(index, 'targetOption', e.target.value)}
                            className="input text-sm"
                          >
                            <option value="">Select option...</option>
                            {targetProduct?.options?.map(option => (
                              <option key={option.name} value={option.name}>
                                {option.name} ({option.values?.length || 0} values)
                              </option>
                            ))}
                          </select>
                        </div>

                        {syncOption.confidence > 0 && (
                          <div className="text-center">
                            <div className={`text-xs font-medium ${
                              syncOption.confidence > 80 ? 'text-green-600' :
                              syncOption.confidence > 60 ? 'text-yellow-600' : 'text-red-600'
                            }`}>
                              {syncOption.confidence}% match
                            </div>
                          </div>
                        )}

                        <button
                          onClick={() => removeSyncOption(index)}
                          className="p-1 text-red-400 hover:text-red-600"
                        >
                          <X className="w-4 h-4" />
                        </button>
                      </div>
                    ))}

                    {variantMapping.syncOptions.length === 0 && !isLoading && (
                      <div className="text-center py-8 text-gray-500">
                        <Settings className="w-12 h-12 mx-auto mb-2 text-gray-300" />
                        <p>No sync rules configured yet</p>
                        <p className="text-sm">Click "Add Sync Rule" to get started</p>
                      </div>
                    )}
                  </div>
                </div>

                {/* Preview Matches */}
                {variantMapping.syncOptions.length > 0 && (
                  <div>
                    <h4 className="font-medium text-gray-900 mb-4 flex items-center">
                      <Info className="w-4 h-4 mr-1" />
                      Preview Variant Matches
                    </h4>

                    <div className="max-h-48 overflow-y-auto border rounded-lg">
                      <table className="w-full text-sm">
                        <thead className="bg-gray-50 sticky top-0">
                          <tr>
                            <th className="px-4 py-2 text-left">Main Product Variant</th>
                            <th className="px-4 py-2 text-left">Target Product Variant</th>
                            <th className="px-4 py-2 text-left">Status</th>
                          </tr>
                        </thead>
                        <tbody>
                          {previewVariantMatches().map((match, index) => (
                            <tr key={index} className="border-t">
                              <td className="px-4 py-2">
                                {match.main.title || `${match.main.option1 || ''} ${match.main.option2 || ''} ${match.main.option3 || ''}`.trim()}
                              </td>
                              <td className="px-4 py-2">
                                {match.target ? (
                                  match.target.title || `${match.target.option1 || ''} ${match.target.option2 || ''} ${match.target.option3 || ''}`.trim()
                                ) : (
                                  <span className="text-gray-400">No match</span>
                                )}
                              </td>
                              <td className="px-4 py-2">
                                {match.match ? (
                                  <span className="inline-flex items-center text-green-600">
                                    <Check className="w-3 h-3 mr-1" />
                                    Match
                                  </span>
                                ) : (
                                  <span className="text-red-600">No match</span>
                                )}
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}
              </>
            )}
          </div>

          {/* Footer */}
          <div className="flex items-center justify-end space-x-3 mt-6 pt-6 border-t">
            <button
              onClick={onClose}
              className="btn-secondary"
            >
              Cancel
            </button>
            <button
              onClick={handleSave}
              className="btn-primary"
            >
              Save Variant Sync
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default VariantMappingModal;
